/* ===== Auto-detect immersive live modal ===== */
.ac-live-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1200;
  background: rgba(2, 6, 18, 0.72);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}

.ac-live-modal {
  position: fixed;
  z-index: 1201;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: min(26.5rem, calc(100vw - 0.85rem));
  max-height: min(94vh, 46rem);
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  padding: 0.75rem 0.8rem 0.9rem;
  border-radius: 1rem;
  border: 1px solid rgba(140, 200, 255, 0.35);
  background:
    radial-gradient(ellipse 90% 55% at 50% -10%, rgba(60, 100, 200, 0.35), transparent 60%),
    linear-gradient(165deg, #0a1228 0%, #050914 55%, #02040c 100%);
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.65), inset 0 0 40px rgba(80, 140, 255, 0.08);
  color: #e8f0ff;
  overflow: hidden;
}

.ac-live-modal__stars,
.ac-live-modal__aurora {
  pointer-events: none;
  position: absolute;
  inset: 0;
}

.ac-live-modal__stars {
  background-image:
    radial-gradient(1.2px 1.2px at 12% 18%, rgba(255,255,255,0.95), transparent),
    radial-gradient(1px 1px at 28% 62%, rgba(200,220,255,0.8), transparent),
    radial-gradient(1.4px 1.4px at 48% 22%, rgba(255,255,255,0.9), transparent),
    radial-gradient(1px 1px at 66% 74%, rgba(255,255,255,0.7), transparent),
    radial-gradient(1.5px 1.5px at 82% 34%, rgba(210,230,255,0.95), transparent),
    radial-gradient(1px 1px at 90% 88%, rgba(255,255,255,0.65), transparent),
    radial-gradient(1.2px 1.2px at 8% 80%, rgba(255,255,255,0.75), transparent);
  opacity: 0.7;
  animation: ac-live-twinkle 4.5s ease-in-out infinite;
}

.ac-live-modal__aurora {
  background:
    radial-gradient(ellipse 70% 40% at 20% 100%, rgba(40, 180, 120, 0.18), transparent 70%),
    radial-gradient(ellipse 60% 35% at 85% 0%, rgba(80, 120, 255, 0.2), transparent 65%);
  animation: ac-live-aurora 7s ease-in-out infinite alternate;
}

@keyframes ac-live-twinkle {
  0%, 100% { opacity: 0.55; }
  50% { opacity: 0.9; }
}

@keyframes ac-live-aurora {
  from { opacity: 0.55; transform: translateY(0); }
  to { opacity: 1; transform: translateY(-6px); }
}

.ac-live-modal__header,
.ac-live-modal__controls,
.ac-live-modal__rate,
.ac-live-modal__stage,
.ac-live-empty {
  position: relative;
  z-index: 1;
}

.ac-live-modal__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.5rem;
}

.ac-live-modal__title {
  margin: 0.15rem 0 0;
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: 0.01em;
}

.ac-live-modal__live {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #9dffb4;
}

.ac-live-modal__live-dot {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: #5dd879;
  box-shadow: 0 0 8px rgba(93, 216, 121, 0.95);
  animation: ac-autodetect-pulse 1.1s ease-in-out infinite;
}

.ac-live-modal__close {
  width: 2rem;
  height: 2rem;
  border: 1px solid rgba(160, 190, 255, 0.25);
  border-radius: 0.45rem;
  background: rgba(255, 255, 255, 0.06);
  color: #dce7fb;
  cursor: pointer;
}

.ac-live-modal__controls {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.ac-live-switch {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.28rem 0.5rem 0.28rem 0.35rem;
  border-radius: 999px;
  border: 1px solid rgba(140, 180, 255, 0.25);
  background: rgba(8, 14, 28, 0.45);
  cursor: pointer;
  user-select: none;
}

.ac-live-switch input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.ac-live-switch__ui {
  width: 1.7rem;
  height: 0.95rem;
  border-radius: 999px;
  background: rgba(120, 140, 180, 0.35);
  position: relative;
  flex: 0 0 auto;
  transition: background 0.15s ease;
}

.ac-live-switch__ui::after {
  content: '';
  position: absolute;
  top: 0.12rem;
  left: 0.12rem;
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 50%;
  background: #e8eefc;
  transition: transform 0.15s ease;
}

.ac-live-switch input:checked + .ac-live-switch__ui {
  background: rgba(93, 216, 121, 0.55);
}

.ac-live-switch input:checked + .ac-live-switch__ui::after {
  transform: translateX(0.72rem);
}

.ac-live-switch__label {
  font-size: 0.68rem;
  font-weight: 700;
  color: #cfe0ff;
}

.ac-live-modal__rate {
  padding: 0.35rem 0.45rem 0.4rem;
  border-radius: 0.55rem;
  border: 1px solid rgba(140, 180, 255, 0.2);
  background: rgba(0, 0, 0, 0.22);
}

.ac-live-modal__rate-head {
  display: flex;
  justify-content: space-between;
  font-size: 0.7rem;
  color: #9fb2d8;
  margin-bottom: 0.2rem;
}

.ac-live-modal__rate-head strong {
  color: #ffe08a;
  font-variant-numeric: tabular-nums;
}

.ac-live-modal__slider {
  width: 100%;
  accent-color: #7ec8ff;
}

.ac-live-modal__rate-ends {
  display: flex;
  justify-content: space-between;
  font-size: 0.58rem;
  color: #7f93b8;
}

.ac-live-modal__stage {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  overflow-y: auto;
  min-height: 0;
  flex: 1 1 auto;
  padding-right: 0.1rem;
}

.ac-live-radar {
  position: relative;
  width: min(100%, 12.5rem);
  aspect-ratio: 1 / 1;
  margin: 0.1rem auto 0.15rem;
  border-radius: 50%;
  border: 1px solid rgba(120, 200, 255, 0.35);
  background:
    radial-gradient(circle at 50% 50%, rgba(40, 90, 160, 0.25) 0%, rgba(8, 14, 28, 0.65) 70%);
  box-shadow: inset 0 0 24px rgba(80, 160, 255, 0.18), 0 0 20px rgba(80, 140, 255, 0.15);
}

.ac-live-radar__ring {
  position: absolute;
  border: 1px dashed rgba(140, 190, 255, 0.28);
  border-radius: 50%;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
}

.ac-live-radar__ring--1 { width: 32%; height: 32%; }
.ac-live-radar__ring--2 { width: 58%; height: 58%; }
.ac-live-radar__ring--3 { width: 84%; height: 84%; }

.ac-live-radar__cross-h,
.ac-live-radar__cross-v {
  position: absolute;
  background: rgba(160, 200, 255, 0.22);
}

.ac-live-radar__cross-h {
  left: 8%;
  right: 8%;
  top: 50%;
  height: 1px;
}

.ac-live-radar__cross-v {
  top: 8%;
  bottom: 8%;
  left: 50%;
  width: 1px;
}

.ac-live-radar__center {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 0.55rem;
  height: 0.55rem;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: #9ed4ff;
  box-shadow: 0 0 10px rgba(120, 200, 255, 0.9);
}

.ac-live-radar__target {
  position: absolute;
  transform: translate(-50%, 50%);
  width: 1.55rem;
  height: 1.55rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.45);
  border: 1px solid currentColor;
  font-size: 0.85rem;
  transition: left 0.2s ease, bottom 0.2s ease;
}

.ac-live-hero {
  display: flex;
  align-items: center;
  gap: 0.7rem;
}

.ac-live-hero__orb {
  --ac-live-accent: #ffd54a;
  flex: 0 0 auto;
  width: 3.6rem;
  height: 3.6rem;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.55rem;
  color: var(--ac-live-accent);
  background:
    radial-gradient(circle at 35% 30%, rgba(255,255,255,0.25), transparent 45%),
    radial-gradient(circle at 50% 50%, color-mix(in srgb, var(--ac-live-accent) 35%, transparent), rgba(0,0,0,0.35));
  border: 1px solid color-mix(in srgb, var(--ac-live-accent) 55%, transparent);
  box-shadow: 0 0 28px color-mix(in srgb, var(--ac-live-accent) 45%, transparent);
  animation: ac-live-orb 2.4s ease-in-out infinite;
}

@keyframes ac-live-orb {
  0%, 100% { transform: scale(1); filter: brightness(1); }
  50% { transform: scale(1.06); filter: brightness(1.15); }
}

.ac-live-hero__kind {
  display: inline-block;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #9ed4ff;
}

.ac-live-hero__name {
  margin: 0.1rem 0 0.15rem;
  font-size: 1.45rem;
  font-weight: 800;
  line-height: 1.1;
  color: #fff8d8;
  text-shadow: 0 0 18px rgba(255, 220, 120, 0.25);
}

.ac-live-hero__sep,
.ac-live-hero__aim {
  margin: 0;
  font-size: 0.7rem;
  color: #b8d0ef;
}

.ac-live-info {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.3rem;
}

.ac-live-info__cell {
  padding: 0.32rem 0.4rem;
  border-radius: 0.4rem;
  background: rgba(0, 0, 0, 0.28);
  border: 1px solid rgba(140, 180, 255, 0.16);
}

.ac-live-info__k {
  display: block;
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #8fa3c8;
}

.ac-live-info__v {
  display: block;
  margin-top: 0.08rem;
  font-size: 0.78rem;
  font-weight: 700;
  color: #eaf1ff;
  font-variant-numeric: tabular-nums;
}

.ac-live-info__v--warn { color: #ffb3a8; }

.ac-live-others {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.ac-live-others__label {
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #9fb2d8;
}

.ac-live-others__btn {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  width: 100%;
  padding: 0.35rem 0.45rem;
  border-radius: 0.4rem;
  border: 1px solid rgba(140, 180, 255, 0.2);
  background: rgba(8, 14, 28, 0.4);
  color: #e8f0ff;
  cursor: pointer;
  text-align: left;
}

.ac-live-others__btn span { flex: 1 1 auto; font-size: 0.78rem; font-weight: 600; }
.ac-live-others__btn em { font-style: normal; font-size: 0.72rem; color: #9ed4ff; font-weight: 800; }

.ac-live-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  min-height: 10rem;
  text-align: center;
  color: #9fb2d8;
  font-size: 0.85rem;
}

.ac-live-empty .fa {
  font-size: 1.8rem;
  color: #7ec8ff;
  opacity: 0.8;
}

@media (max-width: 420px) {
  .ac-live-modal {
    width: calc(100vw - 0.5rem);
    max-height: 96vh;
    border-radius: 0.75rem;
    padding: 0.6rem 0.65rem 0.75rem;
  }
  .ac-live-hero__name { font-size: 1.25rem; }
  .ac-live-radar { width: min(100%, 10.5rem); }
}
\`;
fs.appendFileSync(p, css);
console.log('css ok');
"

